```go
// Setup: Create replicas, R1 commits instance on fast path
r1.CreateInstance(r, i, cmdA, COMMITTED, seq1, deps1)
r1.exec.executeCommand(r, i)

// Simulate partition and recovery with different attributes
r2.CreateInstance(r, i, cmdA, COMMITTED, seq2, deps2)
r2.InstanceSpace[r][i].ballot = 1 // Higher ballot

// Send COMMIT from R2 to R1
commitMsg := &Commit{LeaderId: r2, Replica: r, Instance: i, Seq: seq2, Deps: deps2}
r1.handleCommit(commitMsg)

// Assert: R1 should preserve original attributes
assert(r1.InstanceSpace[r][i].Seq == seq1)
assert(r1.InstanceSpace[r][i].Deps == deps1)
```
